create table if not exists clients(id uuid primary key,organization_id uuid not null references organizations(id) on delete cascade,name varchar(180) not null,email varchar(254),phone varchar(60),address varchar(500),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists idx_clients_org on clients(organization_id);
create table if not exists quotes(id uuid primary key,organization_id uuid not null references organizations(id) on delete cascade,client_id uuid references clients(id) on delete set null,number varchar(40) not null,document_type varchar(20) not null default 'quote',status varchar(30) not null default 'draft',intervention varchar(240) not null,product varchar(240),part_cost numeric(12,2) not null default 0,shipping_cost numeric(12,2) not null default 0,labor_cost numeric(12,2) not null default 0,margin numeric(12,2) not null default 0,vat_rate numeric(5,2) not null default 20,urssaf_rate numeric(5,2) not null default 22,total_ht numeric(12,2) not null default 0,total_tva numeric(12,2) not null default 0,total_ttc numeric(12,2) not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists idx_quotes_org on quotes(organization_id,created_at desc);
create table if not exists appointments(id uuid primary key,organization_id uuid not null references organizations(id) on delete cascade,client_id uuid references clients(id) on delete set null,title varchar(240) not null,starts_at timestamptz not null,ends_at timestamptz,status varchar(30) not null default 'planned',created_at timestamptz not null default now());
create index if not exists idx_appointments_org on appointments(organization_id,starts_at);
